gyroid.source:
// =============================================================================================================================================
// gyroid -- sin x cos y + sin y cos z + sin z cos x, a triply periodic minimal surface. No data; a check that the isosurface works for any
// function. Isosurface: the two interleaved channels at |g| = level, orange where g > 0, blue where g < 0.
// =============================================================================================================================================

// @param 0 frequency 0.1 4 1 log
// @param 1 phase -3.1416 3.1416 0
// @param 3 level 0.01 1.5 0.6 isosurface
// @param 4 scale 0.05 20 1 log
// @param 7 cut 0 3 0 step=1 particles isosurface
// @param 3 brightness 0.001 1 0.04 log particles
// @param 5 size 0.001 0.5 0.015 log particles
// @param 6 step 0.01 4 0.3 log particles
// @param 3 height -10 10 0 surface
// @param 5 plane 0 2 0 step=1 surface
// @param 6 offset -20 20 0 surface

Ir77Sample Sample(vec3 p, float params[8]) {
    vec3 q = p * params[0] + params[1];
    float g = sin(q.x) * cos(q.y) + sin(q.y) * cos(q.z) + sin(q.z) * cos(q.x);

    Ir77Sample s;
    s.value = g;
    s.weight = g * g;
    return s;
}

#include "include/view.glsl"

grid.source:
// =============================================================================================================================================
// grid -- any Compute program's output (format "grid", <project>/data/<name>.json) through include/view.glsl: an isosurface, a cloud, a
// slice. Tick data and pick the file; set the box (x / y / z) to the program's domain to see it at its own size. Between grid points the
// value is trilinear; outside the program's domain it's 0.
//
// ---- the data (version 1) ----------------------------------------------------------------------------------------------------------------
//   header  H     version 1, H (16 + stride), nx, ny, nz, stride, x0, x1, y0, y1, z0, z1, passes, residual, norm, converged, then each
//                 channel's largest |value|
//   points  nx ny nz x stride, x fastest
// =============================================================================================================================================

// @param 0 channel 0 7 0 step=1
// @param 1 relative 0 1 1 step=1
// @param 2 weight 0 1 1 step=1
// @param 3 level 0.0001 1 0.1 log isosurface
// @param 4 scale 0.05 20 1 log
// @param 7 cut 0 3 0 step=1 particles isosurface
// @param 3 brightness 0.001 1 0.04 log particles
// @param 5 size 0.001 0.5 0.03 log particles
// @param 6 step 0.01 4 0.3 log particles
// @param 3 height -10 10 0 surface
// @param 5 plane 0 2 0 step=1 surface
// @param 6 offset -20 20 0 surface
//
// p[0] channel: which of the program's outputs (the data's slider names them)
// p[1] relative: 1 the value over the channel's largest |value| (the level a fraction of it), 0 the value itself
// p[2] weight: the cloud's density -- 1 the value squared (an amplitude, psi), 0 |value| (a density)

#define GRID_VERSION 1u

uint Ir77GridWhole(uint i) { return uint(max(Ir77FieldData(i), 0.0) + 0.5); }

float Ir77GridAt(uint header, uvec3 dims, uint stride, uint channel, ivec3 g) {
    g = clamp(g, ivec3(0), ivec3(dims) - 1);
    return Ir77FieldData(header + (uint(g.x) + uint(g.y) * dims.x + uint(g.z) * dims.x * dims.y) * stride + channel);
}

Ir77Sample Sample(vec3 p, float params[8]) {
    Ir77Sample s;
    s.value = 0.0;
    s.weight = 0.0;
    if (Ir77FieldDataCount() < 16u || Ir77GridWhole(0u) != GRID_VERSION) return s;

    uint header = Ir77GridWhole(1u);
    uvec3 dims = uvec3(max(Ir77GridWhole(2u), 1u), max(Ir77GridWhole(3u), 1u), max(Ir77GridWhole(4u), 1u));
    uint stride = max(Ir77GridWhole(5u), 1u);
    uint channel = min(uint(max(params[0], 0.0) + 0.5), stride - 1u);
    if (header + dims.x * dims.y * dims.z * stride > Ir77FieldDataCount()) return s;

    vec3 lo = vec3(Ir77FieldData(6u), Ir77FieldData(8u), Ir77FieldData(10u));
    vec3 hi = vec3(Ir77FieldData(7u), Ir77FieldData(9u), Ir77FieldData(11u));
    vec3 span = max(hi - lo, vec3(1e-12));
    vec3 t = (p - lo) / span;
    if (any(lessThan(t, vec3(-1e-4))) || any(greaterThan(t, vec3(1.0 + 1e-4)))) return s;

    // trilinear -- a flat axis (one point) is its value
    vec3 f = clamp(t, 0.0, 1.0) * vec3(max(dims, uvec3(2u)) - 1u);
    ivec3 g = ivec3(floor(f));
    vec3 w = f - vec3(g);
    if (dims.x == 1u) w.x = 0.0;
    if (dims.y == 1u) w.y = 0.0;
    if (dims.z == 1u) w.z = 0.0;

    float v = 0.0;
    for (int k = 0; k < 8; k++) {
        ivec3 o = ivec3(k & 1, (k >> 1) & 1, (k >> 2) & 1);
        float wk = (o.x == 1 ? w.x : 1.0 - w.x) * (o.y == 1 ? w.y : 1.0 - w.y) * (o.z == 1 ? w.z : 1.0 - w.z);
        if (wk > 0.0) v += wk * Ir77GridAt(header, dims, stride, channel, g + o);
    }

    float largest = header >= 16u + stride ? Ir77FieldData(16u + channel) : 1.0;
    if (params[1] > 0.5 && largest > 0.0) v /= largest;

    s.value = v;
    s.weight = params[2] > 0.5 ? v * v : abs(v);
    return s;
}

#include "include/view.glsl"
